// formula Homebrew -> kunci logo (mysql@9.7 -> mysql, postgresql@17 -> postgresql, php@8.3 -> php)
function logoFor(formula) {
  const base = String(formula).split("/").pop().replace(/@.*$/, "").replace(/-community$/, "");
  return LOGOS[base] ? base : null;
}

function logoSvg(key, cls = "") {
  const l = LOGOS[key];
  if (!l) return "";
  return `<svg class="logo-i ${l.tone ? "logo-" + l.tone : ""} ${cls}" style="--logo:${l.c}" viewBox="0 0 24 24" role="img" aria-label="${l.t}"><path d="${l.d}"/></svg>`;
}
